class TestCdR13SectionArt {
    private static final SavedDecoder DIRTY=new SavedDecoder(Writer.XOR,0x1234,10,0x89ABCDEF,0x5678,0x9ABC);
    @Test void factoryBindsBothActualSourcePlansWithoutPreparingOrInventingKnownPatterns()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var s=fresh(art,a);assertTrue(art.ownsAssets(a));assertFalse(art.ownsAssets(null));assertSame(a.identity(),art.identity());assertEquals(0xA55A,s.sectionWord());assertEquals(0,knownTiles(s.residency()));assertEquals(0,s.remainingTilesWord());assertTrue(s.decoder().isEmpty());assertSame(DIRTY,s.savedDecoder());assertArrayEquals(dirty().copy(),s.codeTable().copy());assertFalse(s.stopped());}
    }
    @Test void originalActThreeInitAndUpdateRtsPreserveDirtyWordsAndAnActiveDecoderByIdentity()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var s=art.prepare(art.initList(fresh(art,a),3));assertTrue(s.remainingTilesWord()>0);assertSame(s,art.initSection(s));assertSame(s,art.updateSection(s));assertEquals(0xA55A,s.sectionWord());var other=fromAssets(a);assertThrows(IllegalArgumentException.class,()->other.initSection(s));}
    }
    @Test void allSeventeenIdsAndAliasesCopyActualRowsAndClearOnlyTheNativeTuple()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var before=fresh(art,a);for(var list:a.plcs()){var s=art.initList(before,list.nativeId());byte[] rows=new byte[96];for(int i=0;i<list.entries().size();i++){var e=list.entries().get(i);descriptor(rows,i*6,e.sourceNativeAddress(),e.vramAddress());}assertArrayEquals(rows,s.queue().bytes().copy());assertSame(before.codeTable(),s.codeTable());assertSame(before.residency(),s.residency());assertEquals(0,s.remainingTilesWord());assertEquals(Writer.CLEARED,s.savedDecoder().writer());assertEquals(0,s.processBudgetWord());assertEquals(0,s.hintWord());assertEquals(0,s.padWord());assertEquals(before.sectionWord(),s.sectionWord());}assertEquals(art.initList(before,0).queue(),art.initList(before,3).queue());for(int id=5;id<=15;id++)assertEquals(art.initList(before,2).queue(),art.initList(before,id).queue());}
    }
    @Test void appendOverflowRetainsCompletedNativeDescriptorsAndFullQueueScanFailsBeforeWrites()throws Exception{
        var a=actual().good();var art=fromAssets(a);var before=art.appendList(art.appendList(fresh(art,a),1),2);var failure=assertThrows(SectionArtException.class,()->art.appendList(before,2));assertEquals(Reason.DESCRIPTOR_BUFFER,failure.reason());var cause=(CdR11aPlcBuffer.BufferBoundary)failure.getCause();assertEquals(CdR11aPlcBuffer.Access.SOURCE_WRITE,cause.access());assertEquals(96,cause.byteOffset());assertArrayEquals(before.queue().bytes().slice(0,84).copy(),failure.state().queue().bytes().slice(0,84).copy());assertEquals(a.plcs().get(2).entries().get(0).sourceNativeAddress(),failure.state().queue().bytes().unsignedLong(84));assertEquals(a.plcs().get(2).entries().get(1).sourceNativeAddress(),failure.state().queue().bytes().unsignedLong(90));
        byte[] full=new byte[96];for(int at=0;at<96;at+=6)descriptor(full,at,0x200100,0);var input=ingress(art,a,CdR11aPlcBuffer.fromBytes(CdAssetBytes.copyOf(full)));var scan=assertThrows(SectionArtException.class,()->art.appendList(input,2));assertEquals(CdR11aPlcBuffer.Access.SOURCE_SCAN,((CdR11aPlcBuffer.BufferBoundary)scan.getCause()).access());assertArrayEquals(full,scan.state().queue().bytes().copy());assertThrows(IllegalStateException.class,()->art.prepare(scan.state()));
    }
    @Test void everyActualSourceCanBeQueuedAtItsNativeDestinationWithExactPixelsAndReadExtent()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var registry=CdR13SectionSources.fromAssets(a);for(var source:registry.sources()){var before=queued(art,a,source.nativeAddress(),destination(a,source.nativeAddress()));var done=drain(art,before);assertEquals(0,done.remainingTilesWord());assertEquals(0,done.queue().headSource());assertEquals(source.expectedNativeConsumedBytes(),done.decoder().orElseThrow().inputOffset());var expected=new HashMap<Integer,byte[]>();paint(expected,registry,source.id(),destination(a,source.nativeAddress()));image(expected,done.residency());assertEquals(0,knownTiles(before.residency()));}}
    }
    @Test void lastTileUsesTheOriginalEightyEightBytePopWithAllTailBytesPreserved()throws Exception{
        var a=actual().good();var art=fromAssets(a);var r=CdR13SectionSources.fromAssets(a);byte[] raw=new byte[96];for(int at=0;at<96;at+=6)descriptor(raw,at,r.source(ART_RINGS).nativeAddress(),0xF5C0);var before=art.prepare(ingress(art,a,CdR11aPlcBuffer.fromBytes(CdAssetBytes.copyOf(raw))));var done=art.serviceFast(before);var preadvanced=CdR11aPlcBuffer.withHeadDestination(before.queue(),0xF800);var expected=CdR11aPlcBuffer.pop(preadvanced);assertArrayEquals(expected.bytes().copy(),done.queue().bytes().copy());assertArrayEquals(Arrays.copyOfRange(raw,88,96),done.queue().bytes().slice(88,8).copy());assertEquals(0,done.remainingTilesWord());assertSame(before.savedDecoder(),done.savedDecoder());
    }
    @Test void realSlowHighByteAndFastBudgetsRetainTheNativeDestinationPreadvanceAndSavedStores()throws Exception{
        var a=actual().good();var art=fromAssets(a);var r=CdR13SectionSources.fromAssets(a);var before=art.prepare(queued(art,a,r.source(ART_RINGS).nativeAddress(),0xF5C0));var slow=art.serviceSlow(before,0x00FF);assertEquals(11,slow.remainingTilesWord());assertEquals(0xF620,slow.queue().headDestination());assertEquals(0,slow.processBudgetWord());assertEquals(3,knownTiles(slow.residency()));assertEquals(slow.decoder().orElseThrow().sourcePointer(),slow.queue().headSource());
        var fast=art.serviceFast(before);assertEquals(fast,art.serviceSlow(before,0x0100));assertEquals(0,fast.remainingTilesWord());assertEquals(14,knownTiles(fast.residency()));assertEquals(5,fast.processBudgetWord());assertSame(before.savedDecoder(),fast.savedDecoder());assertEquals(0,knownTiles(before.residency()));
    }
    @Test void immediateThreeThenOneUsesRealDecodeOrderAndChangesOnlyTableAndCurrentPatterns()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var before=art.appendList(fresh(art,a),2);var r=CdR13SectionSources.fromAssets(a);var first=art.loadImmediateList(before,3);var done=art.loadImmediateList(first,1);queueExceptTable(before,done);Map<Integer,byte[]> expected=new HashMap<>();paintList(expected,a,r,3);paintList(expected,a,r,1);image(expected,done.residency());assertEquals(0,knownTiles(before.residency()));assertFalse(Arrays.equals(before.codeTable().copy(),done.codeTable().copy()));}
    }
    @Test void nativeRamBlockLoopReturnsTheExistingCompleteProductWithoutWritingPatternsOrQueue()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var before=art.appendList(fresh(art,a),2);var result=art.decodeBlocksToRam(before);assertSame(a.blocksDecode().bytes(),result.blocks());assertEquals(a.identity().file()==CdNativeFile.R13C?6080:6048,result.blocks().length());queueExceptTable(before,result.state());assertSame(before.residency(),result.state().residency());assertEquals(a.blocksDecode().bytes(),result.blocks());}
    }
    @Test void rawLifePeriodsAndMarkerUseFourOriginalTilesWithoutServicingAnActiveDecoder()throws Exception{
        for(var a:actual().all()){var art=fromAssets(a);var before=art.prepare(art.initList(fresh(art,a),3));var raw=CdR13DirectArtSources.fromAssets(a).lifeIcon();for(int period:new int[]{0,1,2,0x80,0x81,0x82}){var done=art.loadLifeIcon(before,period);queue(before,done);Map<Integer,byte[]> expected=new HashMap<>();for(int tile=0;tile<4;tile++)expected.put(0xB420+tile*32,raw.slice((period&127)*128+tile*32,32).copy());image(expected,done.residency());}var bad=assertThrows(SectionArtException.class,()->art.loadLifeIcon(before,3));assertEquals(Reason.LIFE_ICON_SOURCE,bad.reason());assertEquals(Operation.LIFE_ICON,bad.operation());assertEquals(0x2330BCL,bad.sourcePointer());assertEquals(0xB420,bad.destinationByteOffset());terminal(before,bad.state());assertThrows(IllegalArgumentException.class,()->art.loadLifeIcon(before,256));}
    }
    @Test void activeImmediateAndRamCutsPreserveEveryOriginalContinuationValue()throws Exception{
        var a=actual().good();var art=fromAssets(a);var before=art.prepare(art.initList(fresh(art,a),3));for(var op:List.of(Operation.IMMEDIATE_LIST,Operation.BLOCKS_RAM)){var f=assertThrows(SectionArtException.class,()->{if(op==Operation.IMMEDIATE_LIST)art.loadImmediateList(before,1);else art.decodeBlocksToRam(before);});assertEquals(Reason.ACTIVE_QUEUED_DECODE,f.reason());assertEquals(op,f.operation());terminal(before,f.state());assertEquals(before.queue().headSource(),f.sourcePointer());assertTrue(f.completedRamPrefix().isEmpty());}
    }
    @Test void clearResumeAndCapturedValuePreserveOwnerAndCompleteTileStateWithoutMutation()throws Exception{
        var a=actual().good();var art=fromAssets(a);var active=art.serviceSlow(art.prepare(art.initList(fresh(art,a),3)),0);var captured=active;var resumed=art.fromValues(active.codeTable(),active.residency(),active.sectionWord(),active.queue(),active.decoder(),active.savedDecoder(),active.remainingTilesWord(),active.processBudgetWord(),active.hintWord(),active.padWord());assertEquals(active,resumed);assertEquals(drain(art,active),drain(art,resumed));assertSame(captured,active);var clear=art.clearPlcs(active);assertEquals(0,clear.remainingTilesWord());assertTrue(clear.decoder().isEmpty());assertSame(active.codeTable(),clear.codeTable());assertSame(active.residency(),clear.residency());assertEquals(active.sectionWord(),clear.sectionWord());assertEquals(CdR11aPlcBuffer.cleared(),clear.queue());assertTrue(active.remainingTilesWord()>0);assertThrows(IllegalArgumentException.class,()->art.fromValues(dirty(),active.residency(),active.sectionWord(),active.queue(),active.decoder(),active.savedDecoder(),active.remainingTilesWord(),0,0,0));assertThrows(IllegalArgumentException.class,()->art.fromValues(active.codeTable(),active.residency(),active.sectionWord(),CdR11aPlcBuffer.withHeadSource(active.queue(),active.queue().headSource()+2),active.decoder(),active.savedDecoder(),active.remainingTilesWord(),0,0,0));assertThrows(IllegalArgumentException.class,()->art.fromValues(active.codeTable(),active.residency(),active.sectionWord(),active.queue(),active.decoder(),active.savedDecoder(),active.remainingTilesWord()-1,0,0,0));assertThrows(IllegalArgumentException.class,()->art.fromValues(active.codeTable(),active.residency(),active.sectionWord(),active.queue(),active.decoder(),DIRTY,active.remainingTilesWord(),0,0,0));
    }
    @Test void partialResidencyFailureKeepsOneWholeTileAndTheOriginalBudgetPreadvance()throws Exception{
        var a=actual().good();var art=fromAssets(a);var r=CdR13SectionSources.fromAssets(a);var before=art.prepare(queued(art,a,r.source(ART_RINGS).nativeAddress(),0xF760));var f=assertThrows(SectionArtException.class,()->art.serviceFast(before));assertEquals(Reason.RESIDENCY,f.reason());assertEquals(13,f.state().remainingTilesWord());assertEquals(17,f.state().processBudgetWord());assertEquals(0xF9A0,f.state().queue().headDestination());assertEquals(1,knownTiles(f.state().residency()));assertArrayEquals(r.decoded(ART_RINGS).bytes().slice(0,32).copy(),CdR13ArtResidency.readTile(f.state().residency(),0xF760>>>5).copy());assertEquals(0,knownTiles(before.residency()));assertThrows(IllegalStateException.class,()->art.initSection(f.state()));
    }
    @Test void unknownSourcesAndUnknownListsStopWithoutInventingAReaderOrPattern()throws Exception{
        var a=actual().good();var art=fromAssets(a);var before=queued(art,a,0x200100,0);var f=assertThrows(SectionArtException.class,()->art.prepare(before));assertEquals(Reason.UNKNOWN_SOURCE,f.reason());terminal(before,f.state());var list=assertThrows(SectionArtException.class,()->art.loadImmediateList(fresh(art,a),17));assertEquals(Reason.PLC_LIST,list.reason());assertEquals(Operation.IMMEDIATE_LIST,list.operation());assertEquals(0,knownTiles(list.state().residency()));assertThrows(IllegalArgumentException.class,()->art.initList(before,-1));
    }
    @Test void equalIdentityAndWrongProgrammeCannotAcquireTheExactSourceOrCurrentValueOwner()throws Exception{
        var f=actual();var art=fromAssets(f.good());var before=fresh(art,f.good());assertFalse(art.ownsAssets(f.sameGood()));assertFalse(art.ownsAssets(f.bad()));assertThrows(IllegalArgumentException.class,()->fromAssets(f.good()).clearPlcs(before));assertThrows(IllegalArgumentException.class,()->art.fromValues(dirty(),CdR13ArtResidency.unknown(f.sameGood()),0,CdR11aPlcBuffer.cleared(),Optional.empty(),DIRTY,0,0,0,0));assertThrows(IllegalArgumentException.class,()->art.fromValues(dirty(),CdR13ArtResidency.unknown(f.bad()),0,CdR11aPlcBuffer.cleared(),Optional.empty(),DIRTY,0,0,0,0));assertThrows(NullPointerException.class,()->fromAssets(null));
    }
    @Test void explicitPatternClearRetainsQueueDecoderAndScalarsAndLeavesItsInputUnknown()throws Exception{
        var a=actual().good();var art=fromAssets(a);var before=art.prepare(art.initList(fresh(art,a),3));var after=art.clearCurrentPatterns(before);queue(before,after);assertEquals(0,knownTiles(before.residency()));for(var r:CdR13ArtResidency.Region.values())for(int at=0;at<after.residency().region(r).byteLength();at++)assertEquals(0,after.residency().region(r).knownByte(at).orElseThrow());
    }
    static State fresh(CdR13SectionArt art,CdR13FutureAssets a){return ingress(art,a,CdR11aPlcBuffer.cleared());}
    private static State ingress(CdR13SectionArt art,CdR13FutureAssets a,CdR11aPlcBuffer.State queue){return art.fromValues(dirty(),CdR13ArtResidency.unknown(a),0xA55A,queue,Optional.empty(),DIRTY,0,0x2345,0x3456,0x4567);}
    private static State queued(CdR13SectionArt art,CdR13FutureAssets a,long source,int dest){byte[] b=new byte[96];descriptor(b,0,source,dest);return ingress(art,a,CdR11aPlcBuffer.fromBytes(CdAssetBytes.copyOf(b)));}
    static CdAssetBytes dirty(){byte[] b=new byte[512];Arrays.fill(b,(byte)0x5A);return CdAssetBytes.copyOf(b);}
    private static void descriptor(byte[] b,int at,long ptr,int dest){ByteBuffer.wrap(b).putInt(at,(int)ptr).putShort(at+4,(short)dest);}
    private static State drain(CdR13SectionArt art,State s){int calls=0;while(s.queue().headSource()!=0||s.remainingTilesWord()!=0){s=art.serviceFast(art.prepare(s));assertTrue(++calls<2000);}return s;}
    private static int destination(CdR13FutureAssets a,long source){for(var l:a.plcs())for(var e:l.entries())if(e.sourceNativeAddress()==source)return e.vramAddress();throw new AssertionError();}
    private static void paint(Map<Integer,byte[]> out,CdR13SectionSources r,CdR13SectionSources.SourceId id,int dest)throws Exception{var b=r.decoded(id).bytes();for(int at=0;at<b.length();at+=32)out.put(dest+at,b.slice(at,32).copy());}
    private static void paintList(Map<Integer,byte[]> out,CdR13FutureAssets a,CdR13SectionSources r,int id)throws Exception{for(var e:a.plcs().get(id).entries())paint(out,r,r.source(e.sourceNativeAddress()).id(),e.vramAddress());}
    static int knownTiles(CdR13ArtResidency.State s){int n=0;for(var r:CdR13ArtResidency.Region.values())for(int at=0;at<s.region(r).byteLength();at+=32)if(s.region(r).knownByte(at).isPresent())n++;return n;}
    private static void image(Map<Integer,byte[]> expected,CdR13ArtResidency.State state){for(var r:CdR13ArtResidency.Region.values())for(int at=0;at<state.region(r).byteLength();at++){int address=r.destinationWord()+at;var tile=expected.get(address&~31);var v=state.region(r).knownByte(at);if(tile==null)assertTrue(v.isEmpty(),"Unexpected knowledge at "+Integer.toHexString(address));else assertEquals(Byte.toUnsignedInt(tile[address&31]),v.orElseThrow());}}
    private static void queueExceptTable(State a,State b){assertEquals(a.sectionWord(),b.sectionWord());assertSame(a.queue(),b.queue());assertSame(a.decoder().orElse(null),b.decoder().orElse(null));assertSame(a.savedDecoder(),b.savedDecoder());assertEquals(a.remainingTilesWord(),b.remainingTilesWord());assertEquals(a.processBudgetWord(),b.processBudgetWord());assertEquals(a.hintWord(),b.hintWord());assertEquals(a.padWord(),b.padWord());}
    private static void queue(State a,State b){queueExceptTable(a,b);assertSame(a.codeTable(),b.codeTable());}
    private static void terminal(State a,State b){queue(a,b);assertSame(a.residency(),b.residency());assertTrue(b.stopped());}
    record Fixture(CdR13FutureAssets good,CdR13FutureAssets bad,CdR13FutureAssets sameGood){List<CdR13FutureAssets> all(){return List.of(good,bad);}}
    private static Fixture retained;
    static synchronized Fixture actual()throws Exception{if(retained!=null)return retained;String root=System.getProperty("soniccd.media.root");assumeTrue(root!=null&&!root.isBlank(),"Optional original CD media is absent");Path cue;try(var p=Files.list(Path.of(root).resolve("USA"))){var cues=p.filter(f->f.getFileName().toString().toLowerCase(Locale.ROOT).endsWith(".cue")).toList();assertEquals(1,cues.size());cue=cues.getFirst();}try(var programs=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){retained=new Fixture(CdR13FutureAssets.fromPrograms(programs,CdStagePayload.R13C.stage()),CdR13FutureAssets.fromPrograms(programs,CdStagePayload.R13D.stage()),CdR13FutureAssets.fromPrograms(programs,CdStagePayload.R13C.stage()));}return retained;}
    static String hash(byte[] b){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(b));}catch(Exception e){throw new AssertionError(e);}}
}
